// Runs inside the dialog opened by shared/pairing-dialog.ts's showPairingDialog(). Sends the
// entered code back to the parent (commands.ts) via Office.context.ui.messageParent, which
// stores it (pairing-storage.ts) once received there — this page itself doesn't touch storage,
// keeping "who owns the token" in one place.

Office.onReady(() => {
  const codeInput = document.getElementById("code") as HTMLInputElement;
  const okButton = document.getElementById("okButton") as HTMLButtonElement;
  const cancelButton = document.getElementById("cancelButton") as HTMLButtonElement;

  const submit = () => {
    const code = codeInput.value.trim();
    if (code.length > 0) {
      Office.context.ui.messageParent(code);
    }
  };

  okButton.addEventListener("click", submit);
  cancelButton.addEventListener("click", () => Office.context.ui.messageParent(""));
  codeInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      submit();
    }
  });

  codeInput.focus();
});
